+import { createServer } from "http";
+import { claimNext } from "./jobs.ts";
+
+const PORT = process.env.API_PORT ? parseInt(process.env.API_PORT) : 3000;
+
+export const createApiServer = () => {
+  return createServer(async (req, res) => {
+    if (req.url === "/jobs/claim" && req.method === "POST") {
+      try {
+        const job = await claimNext();
+        if (job === null) {
+          res.writeHead(204);
+          res.end();
+          return;
+        }
+        res.writeHead(200, { "Content-Type": "application/json" });
+        res.end(JSON.stringify(job));
+      } catch (error) {
+        console.error("Error claiming job:", error);
+        res.writeHead(500, { "Content-Type": "application/json" });
+        res.end(JSON.stringify({ error: "Failed to claim job" }));
+      }
+    } else {
+      res.writeHead(404, { "Content-Type": "application/json" });
+      res.end(JSON.stringify({ error: "Not found" }));
+    }
+  });
+};
+
+export const runApiServer = () => {
+  const server = createApiServer();
+  server.listen(PORT, () => {
+    console.log(`API server listening on port ${PORT}`);
+  });
+  return server;
+};
